// Set Scale, the overlay rectangle (plan 5.4, tests-first): the stored text "x,y,width,height", its Windows parse and "%.6f" serialisation, and the rewrite a change of
// scale makes (the four values times the factor, the offsets = the scaled x and y). Windows source of truth: overlay_rect.py:17-48 and page_operations.py:84-128.
// Oracle tables: PageScaleTransformOracleData.hpp (generated by running the real Windows functions read-only).
#include "TestHarness.hpp"

#include "Domain/OverlayRect.hpp"
#include "Domain/PageScaleTransform.hpp"

#include "PageScaleTransformOracleData.hpp"

#include <cmath>
#include <limits>
#include <optional>
#include <string>

using namespace ost_domain;
using std::string;

namespace
{
    constexpr double kInfinity = std::numeric_limits<double>::infinity();
    constexpr double kNotANumber = std::numeric_limits<double>::quiet_NaN();

    // units_per_sheet_inch as a number (NaN when the pair has none), so that a missing answer fails a CHECK instead of dereferencing an empty optional.
    double units(double sf1, double sf2)
    {
        const std::optional<double> value = units_per_sheet_inch(sf1, sf2);
        return value ? *value : std::numeric_limits<double>::quiet_NaN();
    }

    const char *kind_name(OverlayRescaleKind kind)
    {
        switch (kind)
        {
        case OverlayRescaleKind::Untouched: return "Untouched";
        case OverlayRescaleKind::Rescaled: return "Rescaled";
        case OverlayRescaleKind::Malformed: return "Malformed";
        case OverlayRescaleKind::NotFinite: return "NotFinite";
        case OverlayRescaleKind::Underflow: return "Underflow";
        case OverlayRescaleKind::BadFactor: return "BadFactor";
        }
        return "?";
    }
}

// ---- parse / serialize (overlay_rect.py:17-48) -----------------------------------------------------------------------------------------------

// overlay_rect.py:33-41 parse_overlay_rect_storage on every row of kRectParseRows (the real Windows function): "", blanks and "*" are the empty rectangle; exactly four
// numbers; Python float() grammar per part (strip, underscores, exponents); NaN / infinity refused; a negative width or height refused; the Windows error texts.
TEST(SetScale_OverlayRect, ParseMatchesWindowsOnEveryOracleRow)
{
    for (const scale_oracle::RectParseRow &row : scale_oracle::kRectParseRows)
    {
        SCOPED_CONTEXT(string("stored '") + row.stored + "'");
        OverlayRect parsed;
        parsed.x = 99.0; // proves an untouched `out` on a refusal
        string error;
        const bool ok = parse_rect_storage(row.stored, parsed, &error);
        CHECK_EQ(ok, row.ok);
        if (row.ok)
        {
            CHECK(ok);
            CHECK_EQ(parsed.x, row.v[0]);
            CHECK_EQ(parsed.y, row.v[1]);
            CHECK_EQ(parsed.width, row.v[2]);
            CHECK_EQ(parsed.height, row.v[3]);
        }
        else
        {
            CHECK_EQ(parsed.x, 99.0);
            CHECK_STR_EQ(error, row.error);
        }
    }
}

// overlay_rect.py:44-48 serialize_overlay_rect_storage on every row of kRectSerializeRows ("%.6f" of the exact value, "-0.000000" kept, huge values in full).
TEST(SetScale_OverlayRect, SerializeMatchesWindowsOnEveryOracleRow)
{
    for (const scale_oracle::RectSerializeRow &row : scale_oracle::kRectSerializeRows)
    {
        SCOPED_CONTEXT(string("expected ") + row.expected);
        OverlayRect rect;
        rect.x = row.v[0];
        rect.y = row.v[1];
        rect.width = row.v[2];
        rect.height = row.v[3];
        string out = "<untouched>";
        REQUIRE(serialize_rect_storage(rect, out));
        CHECK_STR_EQ(out, row.expected);
    }
}

// overlay_rect.py:25-30 _validated_overlay_rect on the way out: a non-finite value or a negative size is refused, `out` untouched.
TEST(SetScale_OverlayRect, SerializeRefusesWhatParseRefuses)
{
    const OverlayRect bad[] = {{0, 0, -1, 1}, {0, 0, 1, -1}, {kNotANumber, 0, 1, 1}, {0, kInfinity, 1, 1}, {0, 0, kInfinity, 1}, {0, 0, 1, -kInfinity}};
    for (const OverlayRect &rect : bad)
    {
        string out = "<untouched>";
        string error;
        CHECK_FALSE(serialize_rect_storage(rect, out, &error));
        CHECK_STR_EQ(out, "<untouched>");
        CHECK(!error.empty());
    }
    string out;
    CHECK(serialize_rect_storage(OverlayRect{0, 0, 0, 0}, out)); // the empty rectangle itself is valid
    CHECK_STR_EQ(out, "0.000000,0.000000,0.000000,0.000000");
}

// Round trip of the stored form: a serialised rectangle parses back to the value within the six decimals, and the empty marker "*" parses to the empty rectangle.
TEST(SetScale_OverlayRect, SerializedTextParsesBackAndTheMarkerIsTheEmptyRectangle)
{
    OverlayRect rect;
    rect.x = -1.654719;
    rect.y = 0.0;
    rect.width = 4029.242135;
    rect.height = 2879.212038;
    string text;
    REQUIRE(serialize_rect_storage(rect, text));
    CHECK_STR_EQ(text, "-1.654719,0.000000,4029.242135,2879.212038");
    OverlayRect parsed;
    REQUIRE(parse_rect_storage(text, parsed));
    CHECK_NEAR(parsed.x, rect.x, 5e-7);
    CHECK_NEAR(parsed.width, rect.width, 5e-7);
    REQUIRE(parse_rect_storage(kEmptyOverlayRectMarker, parsed));
    CHECK_EQ(parsed.width, 0.0);
    CHECK_EQ(parsed.height, 0.0);
}

// ---- the rewrite of a change of scale (page_operations.py:84-128) ---------------------------------------------------------------------------

// page_operations._rescale_page_overlay_rect on every row of kRectRescaleRows: parse, every value times the factor, "%.6f" text, the offsets are the scaled x and y.
TEST(SetScale_OverlayRect, RescaleMatchesWindowsOnEveryOracleRow)
{
    for (const scale_oracle::RectRescaleRow &row : scale_oracle::kRectRescaleRows)
    {
        SCOPED_CONTEXT(string("stored '") + row.stored + "' x " + ost_test::detail::exact_float(row.factor));
        const OverlayRescale got = rescale_overlay_rect(row.stored, row.factor);
        CHECK_STR_EQ(kind_name(got.kind), "Rescaled");
        CHECK_STR_EQ(got.rect_text, row.expected);
        CHECK_EQ(got.offset_x, row.offset_x);
        CHECK_EQ(got.offset_y, row.offset_y);
    }
}

// test_page_operations.py:252 test_page_scale_change_rescales_overlay_rect_and_offsets: stored (0.1875, 12) and rect "-1.103146,0.000000,2686.161423,1919.474692", new
// (0.125, 12): factor 96 / 64 = 1.5, rect "-1.654719,0.000000,4029.242135,2879.212038", offsets -1.654719 and 0.0.
TEST(SetScale_OverlayRect, ScaleChangeRescalesOverlayRectAndOffsets)
{
    const double factor = units(0.125, 12.0) / units(0.1875, 12.0);
    CHECK_EQ(factor, 1.5);
    const OverlayRescale got = rescale_overlay_rect("-1.103146,0.000000,2686.161423,1919.474692", factor);
    CHECK_STR_EQ(kind_name(got.kind), "Rescaled");
    CHECK_STR_EQ(got.rect_text, "-1.654719,0.000000,4029.242135,2879.212038");
    CHECK_EQ(got.offset_x, -1.654719);
    CHECK_EQ(got.offset_y, 0.0);
}

// test_page_operations.py:279 test_page_scale_change_preserves_native_empty_overlay_marker ("*": nothing is written), :285
// test_page_scale_change_leaves_absent_or_zero_size_overlay_rect_untouched (NULL / "", "0.0,0.0,0.0,0.0", "5,5,0,100", "5,5,100,0": nothing is written).
TEST(SetScale_OverlayRect, MarkerAbsentAndZeroSizeRectanglesAreUntouched)
{
    for (const char *stored : {"*", "", "   ", "0.0,0.0,0.0,0.0", "5,5,0,100", "5,5,100,0"})
    {
        SCOPED_CONTEXT(string("stored '") + stored + "'");
        const OverlayRescale got = rescale_overlay_rect(stored, 1.5);
        CHECK_STR_EQ(kind_name(got.kind), "Untouched");
        CHECK_STR_EQ(got.rect_text, "");
    }
}

// test_page_operations.py:293 test_page_scale_change_rejects_malformed_overlay_rect_before_any_write ("0,0,2688", "0,0,abc,1920", "0,0,-1,1920") and the
// non-finite "nan,0,1,1": Malformed, with the Windows ValueError text; the store refuses the whole change before it writes anything.
TEST(SetScale_OverlayRect, MalformedRectanglesAreRefusedWithTheWindowsText)
{
    const struct
    {
        const char *stored;
        const char *error;
    } rows[] = {
        {"0,0,2688", "OverlayRect must contain exactly four values"},
        {"0,0,abc,1920", "OverlayRect values must be numeric"},
        {"0,0,-1,1920", "OverlayRect width and height cannot be negative"},
        {"nan,0,1,1", "OverlayRect values must be finite"},
    };
    for (const auto &row : rows)
    {
        SCOPED_CONTEXT(string("stored '") + row.stored + "'");
        const OverlayRescale got = rescale_overlay_rect(row.stored, 1.5);
        CHECK_STR_EQ(kind_name(got.kind), "Malformed");
        CHECK_STR_EQ(got.error, row.error);
        CHECK_STR_EQ(got.rect_text, "");
    }
}

// test_page_operations.py:621 test_overlay_rectangles_of_any_positive_size_follow_a_scale_change: a rectangle of 0.5 x 0.5 at (0.5, 0.5) on a page that goes from
// (0.125, 12) (96 units per sheet inch) to (0.25, 12) (48): the factor is 0.5, every value becomes 0.25 and both offsets 0.25.
TEST(SetScale_OverlayRect, RectanglesOfAnyPositiveSizeFollowAScaleChange)
{
    const double factor = units(0.25, 12.0) / units(0.125, 12.0);
    CHECK_EQ(factor, 0.5);
    const OverlayRescale got = rescale_overlay_rect("0.500000,0.500000,0.500000,0.500000", factor);
    CHECK_STR_EQ(kind_name(got.kind), "Rescaled");
    CHECK_STR_EQ(got.rect_text, "0.250000,0.250000,0.250000,0.250000");
    CHECK_EQ(got.offset_x, 0.25);
    CHECK_EQ(got.offset_y, 0.25);
}

// ---- iOS-only: the hardening of SS-2 on the rectangle ------------------------------------------------------------------------------------

// A scaled value that is not finite refuses the change (Windows would write "inf"); a non-zero value that underflows to 0.0 too; a bad factor is its own refusal.
TEST(SetScale_OverlayRectSafety, OverflowUnderflowAndABadFactorAreRefused)
{
    CHECK_STR_EQ(kind_name(rescale_overlay_rect("1e308,0,1e308,1e308", 10.0).kind), "NotFinite");
    CHECK_STR_EQ(kind_name(rescale_overlay_rect("0,0,1,1e308", 10.0).kind), "NotFinite");
    CHECK_STR_EQ(kind_name(rescale_overlay_rect("5e-324,0,1,1", 0.5).kind), "Underflow");
    CHECK_STR_EQ(kind_name(rescale_overlay_rect("0,0,5e-324,1", 0.5).kind), "Underflow");
    for (const double bad : {0.0, -1.0, kInfinity, kNotANumber})
    {
        SCOPED_CONTEXT("factor " + ost_test::detail::exact_float(bad));
        CHECK_STR_EQ(kind_name(rescale_overlay_rect("10,20,30,40", bad).kind), "BadFactor");
    }
    CHECK_STR_EQ(kind_name(rescale_overlay_rect("0,0,1e307,1", 10.0).kind), "Rescaled"); // the control: still finite
}

// A refusal carries no text and no offsets. The factor is checked FIRST (a bad factor is BadFactor even for a malformed or an empty rectangle: the store refuses a bad
// factor before it reads any rectangle, so it never gets here with one); then the rectangle is parsed (Malformed), then the multiplication is checked.
TEST(SetScale_OverlayRectSafety, ARefusedRectangleCarriesNoTextAndNoOffsets)
{
    const OverlayRescale overflow = rescale_overlay_rect("1e308,0,1e308,1e308", 10.0);
    CHECK_STR_EQ(overflow.rect_text, "");
    CHECK_EQ(overflow.offset_x, 0.0);
    CHECK_EQ(overflow.offset_y, 0.0);
    CHECK_STR_EQ(kind_name(rescale_overlay_rect("0,0,abc,1920", 1.5).kind), "Malformed");
    CHECK_STR_EQ(kind_name(rescale_overlay_rect("0,0,abc,1920", 0.0).kind), "BadFactor");
}
